export interface DecisionNode {
  id: string;
  title: string;
  decidedAt: number;
  rationale: string;
  parents: string[];
}

export interface RankingHit {
  id: string;
  score: number;
  source: "docs" | "code" | "decisions";
}

export function rankHybrid(
  fts: RankingHit[],
  vec: RankingHit[],
  alpha: number = 0.6
): RankingHit[] {
  const map = new Map<string, RankingHit>();
  for (const h of fts) {
    map.set(h.id, { ...h, score: h.score * (1 - alpha) });
  }
  for (const h of vec) {
    const prev = map.get(h.id);
    if (prev) {
      map.set(h.id, { ...prev, score: prev.score + h.score * alpha });
    } else {
      map.set(h.id, { ...h, score: h.score * alpha });
    }
  }
  return [...map.values()].sort((a, b) => b.score - a.score);
}

export function traverseDecisions(
  nodes: DecisionNode[],
  fromId: string,
  maxDepth: number = 5
): DecisionNode[] {
  const byId = new Map(nodes.map((n) => [n.id, n]));
  const out: DecisionNode[] = [];
  const seen = new Set<string>();
  const queue: Array<{ id: string; depth: number }> = [
    { id: fromId, depth: 0 },
  ];
  while (queue.length) {
    const { id, depth } = queue.shift()!;
    if (seen.has(id) || depth > maxDepth) continue;
    seen.add(id);
    const node = byId.get(id);
    if (!node) continue;
    out.push(node);
    for (const p of node.parents) queue.push({ id: p, depth: depth + 1 });
  }
  return out;
}
